export type LlmsLink = { path: string; title: string; description: string };
export type LlmsSection = { heading: string; intro?: string; links: LlmsLink[] };

const SITE = "https://squarecampus.com";

/** Absolute URL for a route, preferring the Markdown alternate where one exists. */
export function llmsUrl(path: string): string {
  const moved=siteHref("squarecampus",path);
  if(moved!==path) return moved;
  if (path.startsWith("https://")) return path;
  if (path.includes(".")) return `${SITE}${path}`;
  if (hasMarkdownAlternate(path)) return `${SITE}${markdownAlternatePath(path)}`;
  const withSlash = path === "/" ? "/" : path.endsWith("/") ? path : `${path}/`;
  return `${SITE}${withSlash}`;
}

/** Route-only form of a link (`/pricing/`), for the sitemap cross-check. */
export function llmsRoute(path: string): string {
  const p = path.split("#")[0];
  if (p.includes(".")) return p;
  return p === "/" ? "/" : p.endsWith("/") ? p : `${p}/`;
}

const intentPage = (slug: string) => intentPages.find((page) => page.slug === slug);

function intentLink(slug: string, description: string): LlmsLink {
  const page = intentPage(slug);
  if (!page) throw new Error(`llms.ts: unknown intent page "${slug}"`);
  return { path: `/${slug}`, title: page.keyword, description };
}

